// The website's copy of the iPhone web app (apps/website/src/app/shell.js and sw.js, generated by scripts/build.mjs
// --only hosted) is as new as its sources: the hash in each file's first line equals the hash over what esbuild reads for
// it now. A failure here means: run `node scripts/build.mjs --only hosted` and commit the two files with the change.
// Owns: this check. Never: writes the files.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { BANNER, bundleHosted, HOSTED_ENTRIES } from '../../../scripts/hosted-bundle.mjs';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..', '..');

test('the website\'s shell.js and sw.js were built from the current src/ui/hosted', async () => {
  for (const target of HOSTED_ENTRIES) {
    const file = path.join(root, '..', 'website', 'src', 'app', target.file);
    const first = (await readFile(file, 'utf8')).split('\n', 1)[0];
    assert.ok(first.startsWith(BANNER), `${target.file} carries the source hash`);
    const { hash } = await bundleHosted(root, target);
    assert.equal(first.slice(BANNER.length, BANNER.length + 32), hash, `${target.file} is stale: run node scripts/build.mjs --only hosted`);
  }
});
